const express = require('express');
const net = require('net');
const app = express();

// Parse DATABASE_URL from environment (e.g., postgres://user:pass@host:5432/db)
function parseDbUrl(url) {
  if (!url) return { host: 'localhost', port: 5432 };
  const match = url.match(/postgres:\/\/(?:[^:]+:[^@]+@)?([^:]+):(\d+)/);
  if (match) {
    return { host: match[1], port: parseInt(match[2], 10) };
  }
  return { host: 'localhost', port: 5432 };
}

// Check if Postgres is accepting connections on the configured port
function checkDbHealth() {
  return new Promise((resolve) => {
    const dbUrl = process.env.DATABASE_URL || 'postgres://localhost:5432';
    const { host, port } = parseDbUrl(dbUrl);

    const socket = new net.Socket();
    const timeout = 3000; // 3 second timeout for health check

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      socket.destroy();
      resolve({ healthy: true });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ healthy: false });
    });

    socket.on('error', () => {
      socket.destroy();
      resolve({ healthy: false });
    });

    socket.connect(port, host);
  });
}

