const express = require('express');
const net = require('net');
const url = require('url');

const app = express();

// Parse DATABASE_URL from environment
const databaseUrl = process.env.DATABASE_URL;

function getDbConfig(databaseUrl) {
  if (!databaseUrl) {
    return null;
  }

  // Parse postgres://user:pass@host:port/db
  const match = databaseUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
  if (!match) {
    return null;
  }

  return {
    host: match[3],
    port: parseInt(match[4], 10)
  };
}

const dbConfig = getDbConfig(databaseUrl);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/healthz', async (req, res) => {
  if (!dbConfig) {
    return res.status(503).json({ db: 'missing DATABASE_URL' });
  }

  try {
    await checkPort(dbConfig.host, dbConfig.port);
    return res.status(200).json({ db: 'ok' });
  } catch (err) {
    return res.status(503).json({ db: 'error', message: err.message });
  }
});

function checkPort(host, port, timeout = 5000) {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      socket.destroy();
      resolve();
    });

    socket.on('timeout', () => {
      socket.destroy();
      reject(new Error('Connection timed out'));
    });

    socket.on('error', (err) => {
      socket.destroy();
      reject(err);
    });

    socket.connect(port, host);
  });
}

